<?php
use PHPUnit\Framework\TestCase;
use ServSys\Users\Capabilities;
final class Phase9CompletionCodesTest extends TestCase {
 public function test_completion_code_schema_is_versioned_and_many_to_many(): void {$boot=file_get_contents(__DIR__.'/../../servsys.php');$schema=file_get_contents(__DIR__.'/../../src/Database/Schema.php');preg_match("/SERVSYS_DB_VERSION',\\s*(\\d+)/",$boot,$m);$this->assertGreaterThanOrEqual(18,(int)($m[1]??0));$this->assertStringContainsString('servsys_completion_codes',$schema);$this->assertStringContainsString('servsys_service_call_completion_codes',$schema);$this->assertStringContainsString('UNIQUE KEY call_completion_code (service_call_id,completion_code_id)',$schema);foreach(array('description varchar(255) NOT NULL','sort_order int(11) NOT NULL DEFAULT 0','active tinyint(1) NOT NULL DEFAULT 1') as $field){$this->assertStringContainsString($field,$schema);}}
 public function test_catalog_repository_is_company_scoped(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/CompletionCodeRepository.php');$this->assertStringContainsString('CompanyContext::current_company_id()',$p);$this->assertStringContainsString('company_id=%d',$p);$this->assertStringContainsString('active=1',$p);}
 public function test_assignment_repository_is_company_scoped_and_preserves_inactive_history(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/ServiceCallCompletionRepository.php');$this->assertStringContainsString('c.company_id=r.company_id',$p);$this->assertStringContainsString('r.company_id=%d',$p);$this->assertStringContainsString('c.active',$p);}
 public function test_assignment_rejects_cross_company_and_inactive_codes(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/CompletionCodeService.php');$this->assertStringContainsString('Service Call does not belong to the current company.',$p);$this->assertStringContainsString('Completion Code does not belong to this Service Call company.',$p);$this->assertStringContainsString('Inactive Completion Codes cannot be newly assigned.',$p);}
 public function test_catalog_has_no_delete_path(): void {$p=file_get_contents(__DIR__.'/../../src/Admin/CompletionCodesPage.php');$this->assertStringContainsString('Make obsolete codes inactive rather than deleting them',$p);$this->assertStringNotContainsString('delete_completion_code',$p);$this->assertStringNotContainsString('admin_post_servsys_delete_completion_code',$p);}
 public function test_service_call_supports_assign_and_unassign(): void {$p=file_get_contents(__DIR__.'/../../src/Admin/ServiceCallCompletionCodesPage.php');$this->assertStringContainsString('admin_post_servsys_assign_completion_code',$p);$this->assertStringContainsString('admin_post_servsys_unassign_completion_code',$p);$this->assertStringContainsString('Assign Completion Code',$p);$this->assertStringContainsString('(inactive)',$p);}
 public function test_completion_code_permissions_are_company_scoped(): void {foreach(array(Capabilities::VIEW_COMPLETION_CODES,Capabilities::MANAGE_COMPLETION_CODES,Capabilities::ASSIGN_COMPLETION_CODES) as $cap){$this->assertContains($cap,Capabilities::company_capabilities());$this->assertContains($cap,Capabilities::all());}}
 public function test_installer_upgrade_remains_in_place(): void {$p=file_get_contents(__DIR__.'/../../src/Database/Installer.php');$this->assertStringContainsString('if ( $installed < SERVSYS_DB_VERSION )',$p);$this->assertStringContainsString('dbDelta( $sql )',$p);}
}
